import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_activations_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void fused_activations_kernel(const float* input, float* output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float x = input[idx];
        // First LeakyReLU
        x = fmaxf(0.01f * x, x);
        // Second LeakyReLU
        x = fmaxf(0.01f * x, x);
        // First GELU
        float gelu_x = x * 0.5f * (1.0f + tanhf(0.7978845608f * (x + 0.044715f * x * x * x)));
        x = gelu_x;
        // Second GELU
        gelu_x = x * 0.5f * (1.0f + tanhf(0.7978845608f * (x + 0.044715f * x * x * x)));
        output[idx] = gelu_x;
    }
}

torch::Tensor fused_activations_cuda(torch::Tensor input) {
    int size = input.numel();
    auto output = torch::empty_like(input);

    const int block_size = 256;
    int num_blocks = (size + block_size - 1) / block_size;

    fused_activations_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        size
    );

    return output;
}
"""

fused_activations_cpp_source = "torch::Tensor fused_activations_cuda(torch::Tensor input);"

fused_activations = load_inline(
    name='fused_activations',
    cpp_sources=fused_activations_cpp_source,
    cuda_sources=fused_activations_source,
    functions=['fused_activations_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, bias=True):
        super(ModelNew, self).__init__()
        self.linear = nn.Linear(in_features, out_features, bias=bias)
        self.fused_activations = fused_activations

    def forward(self, x):
        x = self.linear(x)
        x = torch.logsumexp(x, dim=1, keepdim=True)
        x = self.fused_activations.fused_activations_cuda(x)
        return x
